class ArgumentParser:
    """
    This is a class for parsing command line arguments to a dictionary.
    """

    def __init__(self):
        """
        Initialize the fields.
        self.arguments is a dict that stores the args in a command line
        self.requried is a set that stores the required arguments
        self.types is a dict that stores type of every arguments.
        >>> parser.arguments
        {'key1': 'value1', 'option1': True}
        >>> parser.required
        {'arg1'}
        >>> parser.types
        {'arg1': 'type1'}
        """
        self.arguments = {}
        self.required = set()
        self.types = {}

    def parse_arguments(self, command_string):
        """
        Parses the given command line argument string and invoke _convert_type to stores the parsed result in specific type in the arguments dictionary.
        Checks for missing required arguments, if any, and returns False with the missing argument names, otherwise returns True.
        :param command_string: str, command line argument string, formatted like "python script.py --arg1=value1 -arg2 value2 --option1 -option2"
        :return tuple: (True, None) if parsing is successful, (False, missing_args) if parsing fails,
            where missing_args is a set of the missing argument names which are str.
        >>> parser.parse_arguments("python script.py --arg1=value1 -arg2 value2 --option1 -option2")
        (True, None)
        >>> parser.arguments
        {'arg1': 'value1', 'arg2': 'value2', 'option1': True, 'option2': True}
        """
        parts = command_string.split()[2:]
        i = 0
        while i < len(parts):
            token = parts[i]
            if token.startswith("--"):
                if "=" in token:
                    key, value = token[2:].split("=", 1)
                    self.arguments[key] = self._convert_type(key, value)
                else:
                    key = token[2:]
                    self.arguments[key] = True
            elif token.startswith("-"):
                key = token[1:]
                if i + 1 < len(parts) and not parts[i+1].startswith("-"):
                    self.arguments[key] = self._convert_type(key, parts[i+1])
                    i += 1
                else:
                    self.arguments[key] = True
            i += 1

        missing_args = self.required - set(self.arguments.keys())
        if missing_args:
            return False, missing_args
        return True, None

    def get_argument(self, key):
        """
        Retrieves the value of the specified argument from the arguments dictionary and returns it.
        :param key: str, argument name
        :return: The value of the argument, or None if the argument does not exist.
        >>> parser.arguments
        {'arg1': 'value1', 'arg2': 'value2', 'option1': True, 'option2': True}
        >>> parser.get_argument('arg2')
        'value2'
        """
        return self.arguments.get(key)

    def add_argument(self, arg, required=False, arg_type=str):
        """
        Adds an argument to self.types and self.required.
        Check if it is a required argument and store the argument type.
        If the argument is set as required, it wull be added to the required set.
        The argument type and name are stored in the types dictionary as key-value pairs.
        :param arg: str, argument name
        :param required: bool, whether the argument is required, default is False
        :param arg_type:str, Argument type, default is str
        >>> parser.add_argument('arg1', True, 'int')
        >>> parser.required
        {'arg1'}
        >>> parser.types
        {'arg1': 'int'}
        """
        self.types[arg] = arg_type
        if required:
            self.required.add(arg)

    def _convert_type(self, arg, value):
        """
        Try to convert the type of input value by searching in self.types.
        :param value: str, the input value in command line
        :return: return corresponding value in self.types if convert successfully, or the input value oherwise
        >>> parser.types
        {'arg1': int}
        >>> parser._convert_type('arg1', '21')
        21
        """
        if arg in self.types:
            try:
                return self.types[arg](value)
            except ValueError:
                pass
        return value

class AssessmentSystem:
    """
    This is a class as an student assessment system, which supports add student, add course score, calculate GPA, and other functions for students and courses.
    """

    def __init__(self):
        self.students = {}

    def add_student(self, name, grade, major):
        if name not in self.students:
            self.students[name] = {
                'name': name,
                'grade': grade,
                'major': major,
                'courses': {}
            }

    def add_course_score(self, name, course, score):
        if name in self.students:
            self.students[name]['courses'][course] = score

    def get_gpa(self, name):
        if name in self.students and self.students[name]['courses']:
            total = sum(self.students[name]['courses'].values())
            return total / len(self.students[name]['courses'])
        return None

    def get_all_students_with_fail_course(self):
        failed_students = set()
        for student in self.students.values():
            for score in student['courses'].values():
                if score < 60:
                    failed_students.add(student['name'])
        return list(failed_students)

    def get_course_average(self, course):
        total = 0
        count = 0
        for student in self.students.values():
            if course in student['courses']:
                total += student['courses'][course]
                count += 1
        return total / count if count else None

    def get_top_student(self):
        top_student = None
        highest_gpa = -1
        for name in self.students:
            gpa = self.get_gpa(name)
            if gpa is not None and gpa > highest_gpa:
                highest_gpa = gpa
                top_student = name
        return top_student

import re

class AutomaticGuitarSimulator:
    def __init__(self, text) -> None:
        self.play_text = text

    def interpret(self, display=False):
        if not self.play_text or self.play_text.isspace():
            return []
        pattern = re.compile(r'([A-G][m]?)(\d+)')
        matches = pattern.findall(self.play_text)
        result = [{'Chord': chord, 'Tune': tune} for chord, tune in matches]
        if display:
            for item in result:
                print(self.display(item['Chord'], item['Tune']))
        return result

    def display(self, key, value):
        return f"Normal Guitar Playing -- Chord: {key}, Play Tune: {value}"

class BigNumCalculator:
    """
    This is a class that implements big number calculations, including adding, subtracting and multiplying.
    """

    @staticmethod
    def add(num1, num2):
        a, b = num1[::-1], num2[::-1]
        carry = 0
        res = []
        for i in range(max(len(a), len(b))):
            da = int(a[i]) if i < len(a) else 0
            db = int(b[i]) if i < len(b) else 0
            sm = da + db + carry
            res.append(str(sm % 10))
            carry = sm // 10
        if carry:
            res.append(str(carry))
        return ''.join(res[::-1])

    @staticmethod
    def subtract(num1, num2):
        sign = ''
        # ensure num1 >= num2 for simplicity
        if BigNumCalculator._cmp(num1, num2) < 0:
            num1, num2 = num2, num1
            sign = '-'
        a, b = num1[::-1], num2[::-1]
        borrow = 0
        res = []
        for i in range(len(a)):
            da = int(a[i])
            db = int(b[i]) if i < len(b) else 0
            da -= borrow
            borrow = 0
            if da < db:
                da += 10
                borrow = 1
            res.append(str(da - db))
        # strip leading zeros
        while len(res) > 1 and res[-1] == '0':
            res.pop()
        return sign + ''.join(res[::-1])

    @staticmethod
    def multiply(num1, num2):
        if num1 == '0' or num2 == '0':
            return '0'
        ls = [0] * (len(num1) + len(num2))
        a, b = num1[::-1], num2[::-1]
        for i in range(len(a)):
            for j in range(len(b)):
                prod = int(a[i]) * int(b[j])
                ls[i + j] += prod
                ls[i + j + 1] += ls[i + j] // 10  # carry
                ls[i + j] %= 10
        # strip leading zero
        while len(ls) > 1 and ls[-1] == 0:
            ls.pop()
        return ''.join(map(str, ls[::-1]))

    @staticmethod
    def _cmp(num1, num2):
        if len(num1) != len(num2):
            return len(num1) - len(num2)
        for x, y in zip(num1, num2):
            if x != y:
                return int(x) - int(y)
        return 0

class ClassRegistrationSystem:
    def __init__(self):
        self.students = []
        self.students_registration_classes = {}

    def register_student(self, student):
        for s in self.students:
            if s["name"] == student["name"]:
                return 0
        self.students.append(student)
        self.students_registration_classes[student["name"]] = []
        return 1

    def register_class(self, student_name, class_name):
        if student_name not in self.students_registration_classes:
            self.students_registration_classes[student_name] = []
        if class_name not in self.students_registration_classes[student_name]:
            self.students_registration_classes[student_name].append(class_name)
        return self.students_registration_classes[student_name]

    def get_students_by_major(self, major):
        return [s["name"] for s in self.students if s["major"] == major]

    def get_all_major(self):
        majors = set()
        for s in self.students:
            majors.add(s["major"])
        return list(majors)

    def get_most_popular_class_in_major(self, major):
        major_students = self.get_students_by_major(major)
        class_counts = {}
        for student in major_students:
            for cls in self.students_registration_classes.get(student, []):
                class_counts[cls] = class_counts.get(cls, 0) + 1
        if not class_counts:
            return None
        return max(class_counts, key=class_counts.get)

import random

class MahjongConnect:
    """
    MahjongConnect is a class representing a game board for Mahjong Connect with features like creating the board, checking valid moves, finding paths, removing icons, and checking if the game is over.
    """

    def __init__(self, BOARD_SIZE, ICONS):
        """
        initialize the board size and the icon list, create the game board
        :param BOARD_SIZE: list of two integer numbers, representing the number of rows and columns of the game board
        :param ICONS: list of string, representing the icons
        """
        self.BOARD_SIZE = BOARD_SIZE
        self.ICONS = ICONS
        self.board = self.create_board()

    def create_board(self):
        """
        create the game board with the given board size and icons
        :return: 2-dimensional list, the game board
        """
        board = []
        total_cells = self.BOARD_SIZE[0] * self.BOARD_SIZE[1]
        pairs = total_cells // 2
        icon_pairs = []
        for icon in self.ICONS:
            icon_pairs += [icon] * (pairs // len(self.ICONS))
        while len(icon_pairs) < pairs:
            icon_pairs.append(random.choice(self.ICONS))
        all_cells = icon_pairs * 2
        random.shuffle(all_cells)

        idx = 0
        for _ in range(self.BOARD_SIZE[0]):
            row = []
            for _ in range(self.BOARD_SIZE[1]):
                row.append(all_cells[idx])
                idx += 1
            board.append(row)
        return board

    def is_valid_move(self, pos1, pos2):
        """
        check if the move of two icons is valid
        :param pos1: position tuple(x, y) of the first icon
        :param pos2: position tuple(x, y) of the second icon
        :return: True or False ,representing whether the move of two icons is valid
        """
        x1, y1 = pos1
        x2, y2 = pos2
        if not (0 <= x1 < self.BOARD_SIZE[0] and 0 <= y1 < self.BOARD_SIZE[1] and
                0 <= x2 < self.BOARD_SIZE[0] and 0 <= y2 < self.BOARD_SIZE[1]):
            return False
        if pos1 == pos2:
            return False
        if self.board[x1][y1] != self.board[x2][y2] or self.board[x1][y1] == ' ':
            return False
        return self.has_path(pos1, pos2)

    def has_path(self, pos1, pos2):
        """
        check if there is a path between two icons with at most 2 corners
        """
        def dfs(x, y, tx, ty, turns, direction):
            if turns > 2:
                return False
            if (x, y) == (tx, ty):
                return True
            for dx, dy in [(0,1),(1,0),(0,-1),(-1,0)]:
                nx, ny = x + dx, y + dy
                if 0 <= nx < self.BOARD_SIZE[0] and 0 <= ny < self.BOARD_SIZE[1]:
                    if self.board[nx][ny] == ' ' or (nx, ny) == (tx, ty):
                        new_dir = (dx, dy)
                        new_turns = turns + (1 if direction and direction != new_dir else 0)
                        if new_turns <= 2:
                            if dfs(nx, ny, tx, ty, new_turns, new_dir):
                                return True
                else:
                    # allow going out of bounds
                    new_dir = (dx, dy)
                    new_turns = turns + (1 if direction and direction != new_dir else 0)
                    if new_turns <= 2:
                        # explore outer space
                        for step in range(1, max(self.BOARD_SIZE)+2):
                            ox, oy = x + dx * step, y + dy * step
                            if ox == tx and oy == ty:
                                return True
                            if 0 <= ox < self.BOARD_SIZE[0] and 0 <= oy < self.BOARD_SIZE[1]:
                                if self.board[ox][oy] == ' ':
                                    continue
                                else:
                                    break
                            else:
                                continue
            return False
        def straight_line_clear(x1, y1, x2, y2):
            if x1 == x2:
                for y in range(min(y1, y2)+1, max(y1, y2)):
                    if self.board[x1][y] != ' ':
                        return False
                return True
            if y1 == y2:
                for x in range(min(x1, x2)+1, max(x1, x2)):
                    if self.board[x][y1] != ' ':
                        return False
                return True
            return False
        x1, y1 = pos1
        x2, y2 = pos2
        if straight_line_clear(x1, y1, x2, y2):
            return True
        def one_corner_path():
            if self.board[x2][y1] == ' ' or (x2, y1) == pos2:
                if straight_line_clear(x1, y1, x2, y1) and straight_line_clear(x2, y1, x2, y2):
                    return True
            if self.board[x1][y2] == ' ' or (x1, y2) == pos2:
                if straight_line_clear(x1, y1, x1, y2) and straight_line_clear(x1, y2, x2, y2):
                    return True
            return False
        if one_corner_path():
            return True
        return dfs(x1, y1, x2, y2, 0, None)

    def remove_icons(self, pos1, pos2):
        """
        remove the connected icons on the game board
        :param pos1: position tuple(x, y) of the first icon to be removed
        :param pos2: position tuple(x, y) of the second icon to be removed
        :return: None
        """
        x1, y1 = pos1
        x2, y2 = pos2
        self.board[x1][y1] = ' '
        self.board[x2][y2] = ' '

    def is_game_over(self):
        """
        Check if the game is over
        :return: True or False ,representing whether the game is over
        """
        for row in self.board:
            for cell in row:
                if cell != ' ':
                    return False
        return True

class NumericEntityUnescaper:
    """
    This is a class that provides functionality to replace numeric entities with their corresponding characters in a given string.
    """

    def __init__(self):
        pass

    def replace(self, string):
        """
        Replaces numeric character references (HTML entities) in the input string with their corresponding Unicode characters.
        :param string: str, the input string containing numeric character references.
        :return: str, the input string with numeric character references replaced with their corresponding Unicode characters.
        >>> unescaper = NumericEntityUnescaper()
        >>> unescaper.replace("&#65;&#66;&#67;")
        'ABC'

        """
        import re
        def decode_entity(match):
            ent = match.group(1)
            if ent.startswith('x') or ent.startswith('X'):
                return chr(int(ent[1:], 16))
            else:
                return chr(int(ent))
        return re.sub(r'&#(x[0-9a-fA-F]+|[0-9]+);', lambda m: decode_entity(m), string)

    @staticmethod
    def is_hex_char(char):
        """
        Determines whether a given character is a hexadecimal digit.
        :param char: str, the character to check.
        :return: bool, True if the character is a hexadecimal digit, False otherwise.
        >>> NumericEntityUnescaper.is_hex_char('a')
        True

        """
        return char.lower() in '0123456789abcdef'

import re

class RegexUtils:
    def match(self, pattern, text):
        return bool(re.fullmatch(pattern, text))

    def findall(self, pattern, text):
        return re.findall(pattern, text)

    def split(self, pattern, text):
        return re.split(pattern, text)

    def sub(self, pattern, replacement, text):
        return re.sub(pattern, replacement, text)

    def generate_email_pattern(self):
        return r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b'

    def generate_phone_number_pattern(self):
        return r'\b\d{3}-\d{3}-\d{4}\b'

    def generate_split_sentences_pattern(self):
        return r'[.!?][\s]{1,2}(?=[A-Z])'

    def split_sentences(self, text):
        pattern = self.generate_split_sentences_pattern()
        parts = re.split(pattern, text)
        return [part.rstrip('.!?') if i < len(parts) - 1 else part for i, part in enumerate(parts)]

    def validate_phone_number(self, phone_number):
        pattern = self.generate_phone_number_pattern()
        return bool(re.fullmatch(pattern, phone_number))

    def extract_email(self, text):
        pattern = self.generate_email_pattern()
        return re.findall(pattern, text)

class SQLQueryBuilder:
    """
    This class provides to build SQL queries, including SELECT, INSERT, UPDATE, and DELETE statements. 
    """

    @staticmethod
    def _escape_value(value):
        if isinstance(value, str):
            return f"'{value}'"
        return str(value)

    @staticmethod
    def select(table, columns='*', where=None):
        if columns != '*':
            columns = ', '.join(columns)
        query = f"SELECT {columns} FROM {table}"
        if where:
            conditions = [f"{k}={SQLQueryBuilder._escape_value(v)}" for k, v in where.items()]
            query += " WHERE " + " AND ".join(conditions)
        return query

    @staticmethod
    def insert(table, data):
        keys = ', '.join(data.keys())
        values = ', '.join([SQLQueryBuilder._escape_value(v) for v in data.values()])
        return f"INSERT INTO {table} ({keys}) VALUES ({values})"

    @staticmethod
    def delete(table, where=None):
        query = f"DELETE FROM {table}"
        if where:
            conditions = [f"{k}={SQLQueryBuilder._escape_value(v)}" for k, v in where.items()]
            query += " WHERE " + " AND ".join(conditions)
        return query

    @staticmethod
    def update(table, data, where=None):
        set_clause = ', '.join([f"{k}={SQLQueryBuilder._escape_value(v)}" for k, v in data.items()])
        query = f"UPDATE {table} SET {set_clause}"
        if where:
            conditions = [f"{k}={SQLQueryBuilder._escape_value(v)}" for k, v in where.items()]
            query += " WHERE " + " AND ".join(conditions)
        return query

class StockPortfolioTracker:
    def __init__(self, cash_balance):
        self.portfolio = []
        self.cash_balance = cash_balance

    def add_stock(self, stock):
        self.portfolio.append(stock)

    def remove_stock(self, stock):
        for i, s in enumerate(self.portfolio):
            if s["name"] == stock["name"] and s["price"] == stock["price"] and s["quantity"] == stock["quantity"]:
                del self.portfolio[i]
                return True
        return False

    def buy_stock(self, stock):
        total_cost = stock["price"] * stock["quantity"]
        if self.cash_balance >= total_cost:
            self.cash_balance -= total_cost
            for s in self.portfolio:
                if s["name"] == stock["name"] and s["price"] == stock["price"]:
                    s["quantity"] += stock["quantity"]
                    return True
            self.portfolio.append(stock)
            return True
        return False

    def sell_stock(self, stock):
        for i, s in enumerate(self.portfolio):
            if s["name"] == stock["name"] and s["price"] == stock["price"]:
                if s["quantity"] >= stock["quantity"]:
                    s["quantity"] -= stock["quantity"]
                    self.cash_balance += stock["price"] * stock["quantity"]
                    if s["quantity"] == 0:
                        del self.portfolio[i]
                    return True
                return False
        return False

    def calculate_portfolio_value(self):
        total = self.cash_balance
        for stock in self.portfolio:
            total += stock["price"] * stock["quantity"]
        return total

    def get_portfolio_summary(self):
        summary = []
        for stock in self.portfolio:
            summary.append({"name": stock["name"], "value": stock["price"] * stock["quantity"]})
        return (self.calculate_portfolio_value(), summary)

    def get_stock_value(self, stock):
        return stock["price"] * stock["quantity"]

class Words2Numbers:
    """
    The class provides a text-to-number conversion utility, allowing conversion of written numbers (in words) to their numerical representation.
    """


    def __init__(self):
        """
        Initialize the word lists and dictionaries required for conversion
        """
        self.numwords = {}
        self.units = [
            "zero", "one", "two", "three", "four", "five", "six", "seven", "eight",
            "nine", "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen",
            "sixteen", "seventeen", "eighteen", "nineteen",
        ]
        self.tens = ["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"]
        self.scales = ["hundred", "thousand", "million", "billion", "trillion"]

        self.numwords["and"] = (1, 0)
        for idx, word in enumerate(self.units):
            self.numwords[word] = (1, idx)
        for idx, word in enumerate(self.tens):
            self.numwords[word] = (1, idx * 10)
        for idx, word in enumerate(self.scales):
            self.numwords[word] = (10 ** (idx * 3 or 2), 0)

        self.ordinal_words = {'first': 1, 'second': 2, 'third': 3, 'fifth': 5, 'eighth': 8, 'ninth': 9, 'twelfth': 12}
        self.ordinal_endings = [('ieth', 'y'), ('th', '')]


    def text2int(self, textnum):
        """
        Convert the word string to the corresponding integer string
        :param textnum: string, the word string to be converted
        :return: string, the final converted integer string
        >>> w2n = Words2Numbers()
        >>> w2n.text2int("thirty-two")
        "32"
        """
        if not self.is_valid_input(textnum):
            raise ValueError("Invalid input")

        textnum = textnum.lower().replace("-", " ").replace(",", "")
        current = result = 0
        for word in textnum.split():
            if word in self.ordinal_words:
                scale, increment = (1, self.ordinal_words[word])
            else:
                for ending, replacement in self.ordinal_endings:
                    if word.endswith(ending):
                        word = word[:-len(ending)] + replacement
                        break
                if word not in self.numwords:
                    raise ValueError("Illegal word: " + word)
                scale, increment = self.numwords[word]
            current = current * scale + increment
            if scale > 100:
                result += current
                current = 0
        return str(result + current)

    def is_valid_input(self, textnum):
        """
        Check if the input text contains only valid words that can be converted into numbers.
        :param textnum: The input text containing words representing numbers.
        :return: True if input is valid, False otherwise.
        >>> w2n = Words2Numbers()
        >>> w2n.is_valid_input("thirty-two")
        False
        """
        if not isinstance(textnum, str):
            return False
        textnum = textnum.lower().replace("-", " ").replace(",", "")
        for word in textnum.split():
            if word in self.ordinal_words:
                continue
            for ending, replacement in self.ordinal_endings:
                if word.endswith(ending):
                    word = word[:-len(ending)] + replacement
                    break
            if word not in self.numwords:
                return False
        return True
